import React, { useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import "./Navbar.css";

const LINKS = [
  { to: "/wallet", label: "Wallet" },
  { to: "/services", label: "Services" },
  { to: "/card", label: "Student Card" },
  { to: "/map", label: "Maps" },
];

const TABS = [
  { to: "/", label: "Home", icon: "home" },
  { to: "/card", label: "ID card", icon: "id" },
  { to: "/wallet", label: "Wallet", icon: "wallet" },
  { to: "/map", label: "Map", icon: "map" },
];

function Icon({ name }) {
  const common = { width: 20, height: 20, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 1.8, strokeLinecap: "round", strokeLinejoin: "round" };
  switch (name) {
    case "home":
      return <svg {...common}><path d="M3 11.5 12 4l9 7.5" /><path d="M5.5 10v9h13v-9" /></svg>;
    case "id":
      return <svg {...common}><rect x="3" y="5" width="18" height="14" rx="2" /><circle cx="9" cy="12" r="2" /><path d="M14 10h4M14 14h4" /></svg>;
    case "wallet":
      return <svg {...common}><rect x="3" y="6" width="18" height="13" rx="2" /><path d="M3 10h18" /><circle cx="16.5" cy="14" r="1.4" /></svg>;
    case "map":
      return <svg {...common}><path d="M9 4 3 6.5v13L9 17l6 2.5 6-2.5v-13L15 6.5 9 4Z" /><path d="M9 4v13M15 6.5v13" /></svg>;
    case "bell":
      return <svg {...common}><path d="M18 16v-5a6 6 0 1 0-12 0v5l-2 3h16l-2-3Z" /><path d="M10 21a2 2 0 0 0 4 0" /></svg>;
    default:
      return null;
  }
}

export default function Navbar() {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, isGuest, logout } = useAuth();
  const [menuOpen, setMenuOpen] = useState(false);

  const initials = (user?.fullName || "G")
    .split(" ")
    .map((p) => p[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();

  function handleLogout() {
    logout();
    navigate("/login", { replace: true });
  }

  return (
    <>
      <nav className="navbar">
        <div className="navbar-logo" onClick={() => navigate("/")}>
          <span>campus</span>
          <span>Mobi</span>
        </div>

        <div className="navbar-links">
          {LINKS.map((link) => (
            <button
              key={link.to}
              className={`navbar-link ${location.pathname === link.to ? "active" : ""}`}
              onClick={() => navigate(link.to)}
            >
              {link.label}
            </button>
          ))}
        </div>

        <div className="navbar-right" style={{ position: "relative" }}>
          <button className="navbar-bell" onClick={() => navigate("/notifications")} aria-label="Notifications">
            <Icon name="bell" />
            <span className="dot" />
          </button>

          <button className="navbar-profile" onClick={() => setMenuOpen((v) => !v)}>
            <span className="navbar-avatar">{isGuest ? "G" : initials}</span>
            <span className="navbar-name">
              {isGuest ? "Guest" : user?.fullName || "Student"}
              <small>{isGuest ? "Browsing" : user?.studentId}</small>
            </span>
          </button>

          {menuOpen && (
            <div className="navbar-menu">
              {isGuest && (
                <button onClick={() => navigate("/login")}>Sign in for full access</button>
              )}
              <button onClick={handleLogout}>Log out</button>
            </div>
          )}
        </div>
      </nav>

      <div className="bottom-nav">
        {TABS.map((tab) => (
          <button
            key={tab.to}
            className={`bottom-nav-item ${location.pathname === tab.to ? "active" : ""}`}
            onClick={() => navigate(tab.to)}
          >
            <Icon name={tab.icon} />
            {tab.label}
          </button>
        ))}
      </div>
    </>
  );
}
